def search_models(query=None, author=None, tags=None, limit=None, **_extra):
    import json, os, datetime, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "search-models"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _client_id():
        if isinstance(_extra, dict):
            for k in ("client_id", "session_id", "caller_id"):
                v = _extra.get(k)
                if isinstance(v, str) and v.strip():
                    return v.strip()
        return "anonymous"

    def _trim_filter(x, name):
        if x is None:
            return None
        if not isinstance(x, str):
            return _err("VALIDATION_ERROR", f"{name} must be a string", field=name)
        v = x.strip()
        if len(v) > 256:
            return _err("VALIDATION_ERROR", f"{name} must not exceed 256 characters", field=name)
        return v

    def _tokenize_tags(s):
        # Consistent across tools: lowercase tokens split on commas/semicolons/whitespace; AND-match.
        s = s.strip().lower()
        parts = re.split(r"[,\s;]+", s)
        toks = []
        seen = set()
        for p in parts:
            p = p.strip()
            if p and p not in seen:
                seen.add(p)
                toks.append(p)
        return toks

    def _norm_params(q, a, tag_tokens, lim):
        return {
            "query": q or "",
            "author": a or "",
            "tags_tokens": tag_tokens or [],
            "limit": lim,
        }

    def _cache_key(norm):
        raw = json.dumps({"tool_name": TOOL, "params": norm}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _new_req_id():
        return "hf_req_" + hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:26].upper()

    def _enforce_limits(hf_requests_rows, cid, norm_key):
        # per-client per-minute
        now = _now()
        win_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in hf_requests_rows:
            if r.get("client_id") != cid:
                continue
            st = _parse_dt(r.get("created_at")) or _parse_dt(r.get("started_at")) or _parse_dt(r.get("updated_at"))
            if st and st >= win_start:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded. Retry later.", retry_after_seconds=60)

        # short-window dedupe (tool_name, norm_key, client_id) within 5s while queued/running
        dedupe_start = now - datetime.timedelta(seconds=5)
        for r in hf_requests_rows:
            if r.get("tool_name") != TOOL:
                continue
            if (r.get("client_id") or None) != cid:
                continue
            if r.get("normalized_cache_key") != norm_key:
                continue
            if r.get("status") not in ("queued", "running"):
                continue
            ct = _parse_dt(r.get("created_at")) or _parse_dt(r.get("started_at"))
            if ct and ct >= dedupe_start:
                return _err("CONFLICT", "Duplicate request in progress", existing_request_id=r.get("id"))
        return None

    # ---- validate inputs ----
    q = _trim_filter(query, "query")
    if isinstance(q, dict) and "error" in q: return q
    a = _trim_filter(author, "author")
    if isinstance(a, dict) and "error" in a: return a
    t = _trim_filter(tags, "tags")
    if isinstance(t, dict) and "error" in t: return t

    if limit is None:
        lim = 20
    else:
        if not isinstance(limit, int) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if not (1 <= limit <= 100):
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")
        lim = limit

    tag_tokens = _tokenize_tags(t) if t else []
    norm = _norm_params(q, a, tag_tokens, lim)
    nck = _cache_key(norm)

    cid = _client_id()
    hf_requests = _load("hf_requests.json")
    if not isinstance(hf_requests, list):
        hf_requests = []

    # enforce quota/rate-limit before creating new request row
    rl_err = _enforce_limits(hf_requests, cid, nck)
    if rl_err:
        return rl_err

    # ---- request log: queued -> running -> succeeded/failed ----
    req_id = _new_req_id()
    created = _now_iso()
    req_row = {
        "id": req_id,
        "tool_name": TOOL,
        "client_id": cid,
        "request_params": {"query": q, "author": a, "tags": t, "limit": lim},
        "normalized_cache_key": nck,
        "status": "queued",
        "http_status_code": None,
        "error_message": None,
        "result_count": None,
        "started_at": None,
        "finished_at": None,
        "cache_hit": False,
        "created_at": created,
        "updated_at": created,
    }
    hf_requests.append(req_row)
    _save("hf_requests.json", hf_requests)

    # transition to running
    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["cache_hit"] = False
    req_row["updated_at"] = _now_iso()
    _save("hf_requests.json", hf_requests)

    try:
        hub_entities = _load("hub_entities.json")
        if not isinstance(hub_entities, list):
            hub_entities = []

        def _matches_text(ent, needle):
            if not needle:
                return True
            n = needle.lower()
            for f in ("repo_id", "name", "description", "author"):
                v = ent.get(f)
                if isinstance(v, str) and n in v.lower():
                    return True
            return False

        def _matches_author(ent, author_filter):
            if not author_filter:
                return True
            v = ent.get("author")
            return isinstance(v, str) and v.strip().lower() == author_filter.lower()

        def _matches_tags(ent, toks):
            if not toks:
                return True
            ent_tags = ent.get("tags")
            if not isinstance(ent_tags, list):
                return False
            low = set()
            for x in ent_tags:
                if isinstance(x, str) and x.strip():
                    low.add(x.strip().lower())
            # AND match on tokens
            for tok in toks:
                if tok not in low:
                    return False
            return True

        rows = []
        for ent in hub_entities:
            if not isinstance(ent, dict):
                continue
            if ent.get("entity_type") != "model":
                continue
            if ent.get("status") == "deleted":
                continue
            if not _matches_text(ent, q):
                continue
            if not _matches_author(ent, a):
                continue
            if not _matches_tags(ent, tag_tokens):
                continue

            rows.append({
                "id": ent.get("id"),
                "model_id": ent.get("repo_id"),
                "author": ent.get("author"),
                "name": ent.get("name"),
                "description": ent.get("description"),
                "tags": ent.get("tags") if isinstance(ent.get("tags"), list) else [],
                "downloads": ent.get("downloads"),
                "likes": ent.get("likes"),
                "last_modified_at": ent.get("last_modified_at"),
            })

        # sort: downloads desc, likes desc, refreshed_at desc
        def _key(ent_row):
            # find original for refreshed_at
            rid = ent_row.get("id")
            src = None
            for e in hub_entities:
                if isinstance(e, dict) and e.get("id") == rid:
                    src = e
                    break
            dls = ent_row.get("downloads")
            lks = ent_row.get("likes")
            ra = _parse_dt(src.get("refreshed_at")) if isinstance(src, dict) else None
            return (-(dls if isinstance(dls, int) else 0), -(lks if isinstance(lks, int) else 0), -(ra.timestamp() if ra else 0))

        rows.sort(key=_key)
        rows = rows[:lim]

        # succeeded
        req_row["status"] = "succeeded"
        req_row["finished_at"] = _now_iso()
        req_row["result_count"] = len(rows)
        req_row["cache_hit"] = True  # served from local cache/datastore
        req_row["updated_at"] = _now_iso()
        _save("hf_requests.json", hf_requests)

        return {"data": rows, "meta": {"limit": lim, "returned": len(rows), "latency_ms": int((time.time() - t0) * 1000)}}
    except Exception as e:
        # failed
        req_row["status"] = "failed"
        req_row["finished_at"] = _now_iso()
        req_row["error_message"] = str(e)
        req_row["cache_hit"] = False
        req_row["updated_at"] = _now_iso()
        _save("hf_requests.json", hf_requests)
        return _err("UPSTREAM_ERROR", "Search failed", detail=str(e))

def get_model_info(model_id, **_extra):
    import json, os, datetime, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "get-model-info"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _client_id():
        if isinstance(_extra, dict):
            for k in ("client_id", "session_id", "caller_id"):
                v = _extra.get(k)
                if isinstance(v, str) and v.strip():
                    return v.strip()
        return "anonymous"

    def _new_req_id():
        return "hf_req_" + hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:26].upper()

    def _cache_key(mid):
        raw = json.dumps({"tool_name": TOOL, "model_id": mid.strip()}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    # validate
    if model_id is None or not isinstance(model_id, str) or not model_id.strip():
        return _err("VALIDATION_ERROR", "model_id must be a non-empty string", field="model_id")
    mid = model_id.strip()
    if len(mid) > 256:
        return _err("VALIDATION_ERROR", "model_id must not exceed 256 characters", field="model_id")

    cid = _client_id()
    nck = _cache_key(mid)
    hf_requests = _load("hf_requests.json")
    if not isinstance(hf_requests, list):
        hf_requests = []

    # rate-limit: 60/min per client
    now = _now()
    win_start = now - datetime.timedelta(seconds=60)
    cnt = 0
    for r in hf_requests:
        if r.get("client_id") != cid:
            continue
        ct = _parse_dt(r.get("created_at")) or _parse_dt(r.get("started_at")) or _parse_dt(r.get("updated_at"))
        if ct and ct >= win_start:
            cnt += 1
    if cnt >= 60:
        return _err("RATE_LIMIT", "Rate limit exceeded. Retry later.", retry_after_seconds=60)

    # log queued
    req_id = _new_req_id()
    created = _now_iso()
    req_row = {
        "id": req_id,
        "tool_name": TOOL,
        "client_id": cid,
        "request_params": {"model_id": mid},
        "normalized_cache_key": nck,
        "status": "queued",
        "http_status_code": None,
        "error_message": None,
        "result_count": None,
        "started_at": None,
        "finished_at": None,
        "cache_hit": False,
        "created_at": created,
        "updated_at": created,
    }
    hf_requests.append(req_row)
    _save("hf_requests.json", hf_requests)

    # running
    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["cache_hit"] = False
    req_row["updated_at"] = _now_iso()
    _save("hf_requests.json", hf_requests)

    try:
        hub_entities = _load("hub_entities.json")
        if not isinstance(hub_entities, list):
            hub_entities = []

        ent = None
        for e in hub_entities:
            if isinstance(e, dict) and e.get("entity_type") == "model" and e.get("repo_id") == mid and e.get("status") != "deleted":
                ent = e
                break

        if ent is None:
            req_row["status"] = "failed"
            req_row["finished_at"] = _now_iso()
            req_row["error_message"] = f"Model not found: {mid}"
            req_row["http_status_code"] = 404
            req_row["cache_hit"] = False
            req_row["updated_at"] = _now_iso()
            _save("hf_requests.json", hf_requests)
            return _err("NOT_FOUND", f"No model exists at id '{mid}'", model_id=mid)

        # TTL: if refreshed_at older than 6h, mark stale (but serve from cache; offline)
        TTL_SECONDS = 6 * 60 * 60
        ra = _parse_dt(ent.get("refreshed_at"))
        stale = (ra is None) or ((_now() - ra).total_seconds() > TTL_SECONDS)
        cache_hit = True
        if stale and ent.get("status") == "active":
            # legal transition active -> stale
            ent["status"] = "stale"
            ent["updated_at"] = _now_iso()
            _save("hub_entities.json", hub_entities)

        payload = {
            "id": ent.get("id"),
            "model_id": ent.get("repo_id"),
            "author": ent.get("author"),
            "name": ent.get("name"),
            "description": ent.get("description"),
            "tags": ent.get("tags") if isinstance(ent.get("tags"), list) else [],
            "downloads": ent.get("downloads"),
            "likes": ent.get("likes"),
            "last_modified_at": ent.get("last_modified_at"),
            "card_data": ent.get("card_data"),
            "status": ent.get("status"),
            "refreshed_at": ent.get("refreshed_at"),
        }

        req_row["status"] = "succeeded"
        req_row["finished_at"] = _now_iso()
        req_row["result_count"] = 1
        req_row["cache_hit"] = cache_hit
        req_row["http_status_code"] = 200
        req_row["updated_at"] = _now_iso()
        _save("hf_requests.json", hf_requests)

        return {"data": payload, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}
    except Exception as e:
        req_row["status"] = "failed"
        req_row["finished_at"] = _now_iso()
        req_row["error_message"] = str(e)
        req_row["cache_hit"] = False
        req_row["updated_at"] = _now_iso()
        _save("hf_requests.json", hf_requests)
        return _err("UPSTREAM_ERROR", "Upstream unavailable", detail=str(e))

def search_datasets(query=None, author=None, tags=None, limit=None, **_extra):
    import json, os, datetime, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "search-datasets"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _client_id():
        if isinstance(_extra, dict):
            for k in ("client_id", "session_id", "caller_id"):
                v = _extra.get(k)
                if isinstance(v, str) and v.strip():
                    return v.strip()
        return "anonymous"

    def _trim_filter(x, name):
        if x is None:
            return None
        if not isinstance(x, str):
            return _err("VALIDATION_ERROR", f"{name} must be a string", field=name)
        v = x.strip()
        if len(v) > 256:
            return _err("VALIDATION_ERROR", f"{name} must not exceed 256 characters", field=name)
        return v

    def _tokenize_tags(s):
        s = s.strip().lower()
        parts = re.split(r"[,\s;]+", s)
        toks = []
        seen = set()
        for p in parts:
            p = p.strip()
            if p and p not in seen:
                seen.add(p)
                toks.append(p)
        return toks

    def _cache_key(norm):
        raw = json.dumps({"tool_name": TOOL, "params": norm}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _new_req_id():
        return "hf_req_" + hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:26].upper()

    # validate
    q = _trim_filter(query, "query")
    if isinstance(q, dict) and "error" in q: return q
    a = _trim_filter(author, "author")
    if isinstance(a, dict) and "error" in a: return a
    t = _trim_filter(tags, "tags")
    if isinstance(t, dict) and "error" in t: return t

    if limit is None:
        lim = 20
    else:
        if not isinstance(limit, int) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if not (1 <= limit <= 100):
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")
        lim = limit

    tag_tokens = _tokenize_tags(t) if t else []
    norm = {"query": q or "", "author": a or "", "tags_tokens": tag_tokens, "limit": lim}
    nck = _cache_key(norm)
    cid = _client_id()

    hf_requests = _load("hf_requests.json")
    if not isinstance(hf_requests, list):
        hf_requests = []

    # rate-limit
    now = _now()
    win_start = now - datetime.timedelta(seconds=60)
    cnt = 0
    for r in hf_requests:
        if r.get("client_id") != cid:
            continue
        ct = _parse_dt(r.get("created_at")) or _parse_dt(r.get("started_at")) or _parse_dt(r.get("updated_at"))
        if ct and ct >= win_start:
            cnt += 1
    if cnt >= 60:
        return _err("RATE_LIMIT", "Rate limit exceeded. Retry later.", retry_after_seconds=60)

    # log queued
    req_id = _new_req_id()
    created = _now_iso()
    req_row = {
        "id": req_id,
        "tool_name": TOOL,
        "client_id": cid,
        "request_params": {"query": q, "author": a, "tags": t, "limit": lim},
        "normalized_cache_key": nck,
        "status": "queued",
        "http_status_code": None,
        "error_message": None,
        "result_count": None,
        "started_at": None,
        "finished_at": None,
        "cache_hit": False,
        "created_at": created,
        "updated_at": created,
    }
    hf_requests.append(req_row)
    _save("hf_requests.json", hf_requests)

    # running
    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["cache_hit"] = False
    req_row["updated_at"] = _now_iso()
    _save("hf_requests.json", hf_requests)

    try:
        hub_entities = _load("hub_entities.json")
        if not isinstance(hub_entities, list):
            hub_entities = []

        def _matches_text(ent, needle):
            if not needle:
                return True
            n = needle.lower()
            for f in ("repo_id", "name", "description", "author"):
                v = ent.get(f)
                if isinstance(v, str) and n in v.lower():
                    return True
            return False

        def _matches_author(ent, author_filter):
            if not author_filter:
                return True
            v = ent.get("author")
            return isinstance(v, str) and v.strip().lower() == author_filter.lower()

        def _matches_tags(ent, toks):
            if not toks:
                return True
            ent_tags = ent.get("tags")
            if not isinstance(ent_tags, list):
                return False
            low = set()
            for x in ent_tags:
                if isinstance(x, str) and x.strip():
                    low.add(x.strip().lower())
            for tok in toks:
                if tok not in low:
                    return False
            return True

        rows = []
        for ent in hub_entities:
            if not isinstance(ent, dict):
                continue
            if ent.get("entity_type") != "dataset":
                continue
            if ent.get("status") == "deleted":
                continue
            if not _matches_text(ent, q):
                continue
            if not _matches_author(ent, a):
                continue
            if not _matches_tags(ent, tag_tokens):
                continue

            rows.append({
                "id": ent.get("id"),
                "dataset_id": ent.get("repo_id"),
                "author": ent.get("author"),
                "name": ent.get("name"),
                "description": ent.get("description"),
                "tags": ent.get("tags") if isinstance(ent.get("tags"), list) else [],
                "downloads": ent.get("downloads"),
                "likes": ent.get("likes"),
                "last_modified_at": ent.get("last_modified_at"),
            })

        def _key(rw):
            rid = rw.get("id")
            src = None
            for e in hub_entities:
                if isinstance(e, dict) and e.get("id") == rid:
                    src = e
                    break
            dls = rw.get("downloads")
            lks = rw.get("likes")
            ra = _parse_dt(src.get("refreshed_at")) if isinstance(src, dict) else None
            return (-(dls if isinstance(dls, int) else 0), -(lks if isinstance(lks, int) else 0), -(ra.timestamp() if ra else 0))

        rows.sort(key=_key)
        rows = rows[:lim]

        req_row["status"] = "succeeded"
        req_row["finished_at"] = _now_iso()
        req_row["result_count"] = len(rows)
        req_row["cache_hit"] = True
        req_row["updated_at"] = _now_iso()
        _save("hf_requests.json", hf_requests)

        return {"data": rows, "meta": {"limit": lim, "returned": len(rows), "latency_ms": int((time.time() - t0) * 1000)}}
    except Exception as e:
        req_row["status"] = "failed"
        req_row["finished_at"] = _now_iso()
        req_row["error_message"] = str(e)
        req_row["cache_hit"] = False
        req_row["updated_at"] = _now_iso()
        _save("hf_requests.json", hf_requests)
        return _err("UPSTREAM_ERROR", "Search failed", detail=str(e))

def get_dataset_info(dataset_id, **_extra):
    import json, os, datetime, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    TOOL = "get-dataset-info"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _client_id():
        if isinstance(_extra, dict):
            for k in ("client_id", "session_id", "caller_id"):
                v = _extra.get(k)
                if isinstance(v, str) and v.strip():
                    return v.strip()
        # Ambient auth: pick a plausible client_id from existing request logs if any.
        reqs = _load("hf_requests.json")
        if isinstance(reqs, list):
            for r in reversed(reqs):
                cid = r.get("client_id")
                if isinstance(cid, str) and cid.strip():
                    return cid.strip()
        return None

    def _new_req_id():
        # short ULID-like stable length, but using sha256 for offline deterministic uniqueness
        return "hf_req_" + hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:26].upper()

    def _cache_key(did):
        norm = {"dataset_id": did}
        raw = json.dumps({"tool_name": TOOL, "params": norm}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _log_init(hf_requests, cid, params, nck):
        now_iso = _now_iso()
        rid = _new_req_id()
        row = {
            "id": rid,
            "tool_name": TOOL,
            "client_id": cid,
            "request_params": params,
            "normalized_cache_key": nck,
            "status": "queued",
            "http_status_code": None,
            "error_message": None,
            "result_count": None,
            "started_at": None,
            "finished_at": None,
            "cache_hit": False,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        hf_requests.append(row)
        _save("hf_requests.json", hf_requests)
        return rid

    def _log_transition(hf_requests, req_id, new_status, **updates):
        # enforce lifecycle transitions
        transitions = {
            "queued": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        now_iso = _now_iso()
        for r in hf_requests:
            if r.get("id") == req_id:
                cur = r.get("status")
                if cur not in transitions:
                    return False, _err("INVALID_TRANSITION", "Unknown current request status", id=req_id, status=cur)
                if new_status not in transitions[cur]:
                    return False, _err("INVALID_TRANSITION", "Illegal status transition", id=req_id, from_status=cur, to_status=new_status)
                # cache_hit must be false when queued/running
                if new_status in ("queued", "running"):
                    r["cache_hit"] = False
                r["status"] = new_status
                r["updated_at"] = now_iso
                for k, v in updates.items():
                    r[k] = v
                # finished_at >= started_at constraint is checked by caller setting values sensibly
                _save("hf_requests.json", hf_requests)
                return True, r
        return False, _err("NOT_FOUND", "Request log entry not found for transition", id=req_id)

    # validate
    if dataset_id is None or not isinstance(dataset_id, str) or not dataset_id.strip():
        return _err("VALIDATION_ERROR", "dataset_id must be a non-empty string", field="dataset_id")
    did = dataset_id.strip()
    if len(did) > 256:
        return _err("VALIDATION_ERROR", "dataset_id must not exceed 256 characters", field="dataset_id")

    cid = _client_id()
    nck = _cache_key(did)

    hf_requests = _load("hf_requests.json")
    if not isinstance(hf_requests, list):
        hf_requests = []

    # simple per-client rate limit: 60/minute; if cid missing, treat as shared bucket "anonymous"
    now = _now()
    win_start = now - datetime.timedelta(seconds=60)
    bucket = cid or "anonymous"
    recent = 0
    for r in hf_requests:
        if r.get("client_id") == bucket:
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= win_start:
                recent += 1
    if recent >= 60:
        # still must log the call attempt
        req_id = _log_init(hf_requests, bucket, {"dataset_id": did}, nck)
        ok, _ = _log_transition(_load("hf_requests.json"), req_id, "failed", started_at=_now_iso(), finished_at=_now_iso(), error_message="Rate limit exceeded", http_status_code=429)
        return _err("RATE_LIMIT", "Rate limit exceeded. Retry later.", retry_after_seconds=60)

    # create request row and run
    req_id = _log_init(hf_requests, bucket, {"dataset_id": did}, nck)
    hf_requests = _load("hf_requests.json")
    started_iso = _now_iso()
    ok, res = _log_transition(hf_requests, req_id, "running", started_at=started_iso)
    if not ok:
        return res

    # cache/TTL behavior: mark stale if refreshed_at older than TTL; try to "refresh" (offline => cannot), serve stale if present
    TTL_SECONDS = 24 * 3600
    hub = _load("hub_entities.json")
    if not isinstance(hub, list):
        hub = []

    entity = None
    for e in hub:
        if e.get("entity_type") == "dataset" and e.get("repo_id") == did:
            entity = e
            break

    finished_iso = _now_iso()

    if entity is None:
        # offline: no upstream; real service would fetch & upsert, but here we must not fabricate
        hf_requests = _load("hf_requests.json")
        _log_transition(
            hf_requests,
            req_id,
            "failed",
            finished_at=finished_iso,
            error_message=f"No dataset exists at id '{did}'",
            http_status_code=404,
            result_count=0,
            cache_hit=False,
        )
        return _err("NOT_FOUND", f"No dataset exists at id '{did}'", dataset_id=did)

    # check TTL and mark stale on read if needed
    refreshed_at = _parse_dt(entity.get("refreshed_at"))
    is_stale = False
    if refreshed_at is None:
        is_stale = True
    else:
        age = (now - refreshed_at).total_seconds()
        if age > TTL_SECONDS:
            is_stale = True

    cache_hit = True
    if is_stale and entity.get("status") in ("active", "stale"):
        # mark stale on read
        if entity.get("status") != "stale":
            # enforce lifecycle transitions
            if entity.get("status") == "active":
                entity["status"] = "stale"
                entity["updated_at"] = _now_iso()
                _save("hub_entities.json", hub)
        # offline: cannot refresh; serve stale snapshot as cache_hit=true
        cache_hit = True

    # success
    hf_requests = _load("hf_requests.json")
    _log_transition(
        hf_requests,
        req_id,
        "succeeded",
        finished_at=finished_iso,
        http_status_code=200,
        error_message=None,
        result_count=1,
        cache_hit=cache_hit,
    )

    # return entity (never fabricate)
    return {
        "dataset": entity,
        "meta": {
            "request_id": req_id,
            "cache_hit": cache_hit,
        },
    }

def search_spaces(query=None, author=None, tags=None, sdk=None, limit=None, **_extra):
    import json, os, datetime, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "search-spaces"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _client_id():
        if isinstance(_extra, dict):
            for k in ("client_id", "session_id", "caller_id"):
                v = _extra.get(k)
                if isinstance(v, str) and v.strip():
                    return v.strip()
        return "anonymous"

    def _trim_filter(x, name):
        if x is None:
            return None
        if not isinstance(x, str):
            return _err("VALIDATION_ERROR", f"{name} must be a string", field=name)
        v = x.strip()
        if len(v) > 256:
            return _err("VALIDATION_ERROR", f"{name} must not exceed 256 characters", field=name)
        return v

    def _tokenize_tags(s):
        s = s.strip().lower()
        parts = re.split(r"[,\s;]+", s)
        toks = []
        seen = set()
        for p in parts:
            p = p.strip()
            if p and p not in seen:
                seen.add(p)
                toks.append(p)
        return toks

    def _cache_key(norm):
        raw = json.dumps({"tool_name": TOOL, "params": norm}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _new_req_id():
        return "hf_req_" + hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:26].upper()

    # validate
    q = _trim_filter(query, "query")
    if isinstance(q, dict) and "error" in q: return q
    a = _trim_filter(author, "author")
    if isinstance(a, dict) and "error" in a: return a
    t = _trim_filter(tags, "tags")
    if isinstance(t, dict) and "error" in t: return t
    s = _trim_filter(sdk, "sdk")
    if isinstance(s, dict) and "error" in s: return s

    if limit is None:
        lim = 20
    else:
        if not isinstance(limit, int) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if not (1 <= limit <= 100):
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")
        lim = limit

    tag_tokens = _tokenize_tags(t) if t else []
    norm = {"query": q or "", "author": a or "", "tags_tokens": tag_tokens, "sdk": s or "", "limit": lim}
    nck = _cache_key(norm)
    cid = _client_id()

    hf_requests = _load("hf_requests.json")
    if not isinstance(hf_requests, list):
        hf_requests = []

    # rate-limit
    now = _now()
    win_start = now - datetime.timedelta(seconds=60)
    cnt = 0
    for r in hf_requests:
        if r.get("client_id") != cid:
            continue
        ct = _parse_dt(r.get("created_at")) or _parse_dt(r.get("started_at")) or _parse_dt(r.get("updated_at"))
        if ct and ct >= win_start:
            cnt += 1
    if cnt >= 60:
        return _err("RATE_LIMIT", "Rate limit exceeded. Retry later.", retry_after_seconds=60)

    # queued
    req_id = _new_req_id()
    created = _now_iso()
    req_row = {
        "id": req_id,
        "tool_name": TOOL,
        "client_id": cid,
        "request_params": {"query": q, "author": a, "tags": t, "sdk": s, "limit": lim},
        "normalized_cache_key": nck,
        "status": "queued",
        "http_status_code": None,
        "error_message": None,
        "result_count": None,
        "started_at": None,
        "finished_at": None,
        "cache_hit": False,
        "created_at": created,
        "updated_at": created,
    }
    hf_requests.append(req_row)
    _save("hf_requests.json", hf_requests)

    # running
    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["cache_hit"] = False
    req_row["updated_at"] = _now_iso()
    _save("hf_requests.json", hf_requests)

    try:
        hub_entities = _load("hub_entities.json")
        if not isinstance(hub_entities, list):
            hub_entities = []

        def _matches_text(ent, needle):
            if not needle:
                return True
            n = needle.lower()
            for f in ("repo_id", "name", "description", "author"):
                v = ent.get(f)
                if isinstance(v, str) and n in v.lower():
                    return True
            return False

        def _matches_author(ent, author_filter):
            if not author_filter:
                return True
            v = ent.get("author")
            return isinstance(v, str) and v.strip().lower() == author_filter.lower()

        def _matches_sdk(ent, sdk_filter):
            if not sdk_filter:
                return True
            v = ent.get("sdk")
            return isinstance(v, str) and v.strip().lower() == sdk_filter.lower()

        def _matches_tags(ent, toks):
            if not toks:
                return True
            ent_tags = ent.get("tags")
            if not isinstance(ent_tags, list):
                return False
            low = set()
            for x in ent_tags:
                if isinstance(x, str) and x.strip():
                    low.add(x.strip().lower())
            for tok in toks:
                if tok not in low:
                    return False
            return True

        rows = []
        for ent in hub_entities:
            if not isinstance(ent, dict):
                continue
            if ent.get("entity_type") != "space":
                continue
            if ent.get("status") == "deleted":
                continue
            if not _matches_text(ent, q):
                continue
            if not _matches_author(ent, a):
                continue
            if not _matches_tags(ent, tag_tokens):
                continue
            if not _matches_sdk(ent, s):
                continue

            rows.append({
                "id": ent.get("id"),
                "space_id": ent.get("repo_id"),
                "author": ent.get("author"),
                "name": ent.get("name"),
                "description": ent.get("description"),
                "tags": ent.get("tags") if isinstance(ent.get("tags"), list) else [],
                "sdk": ent.get("sdk"),
                "likes": ent.get("likes"),
                "last_modified_at": ent.get("last_modified_at"),
            })

        def _key(rw):
            rid = rw.get("id")
            src = None
            for e in hub_entities:
                if isinstance(e, dict) and e.get("id") == rid:
                    src = e
                    break
            lks = rw.get("likes")
            ra = _parse_dt(src.get("refreshed_at")) if isinstance(src, dict) else None
            return (-(lks if isinstance(lks, int) else 0), -(ra.timestamp() if ra else 0))

        rows.sort(key=_key)
        rows = rows[:lim]

        req_row["status"] = "succeeded"
        req_row["finished_at"] = _now_iso()
        req_row["result_count"] = len(rows)
        req_row["cache_hit"] = True
        req_row["updated_at"] = _now_iso()
        _save("hf_requests.json", hf_requests)

        return {"data": rows, "meta": {"limit": lim, "returned": len(rows), "latency_ms": int((time.time() - t0) * 1000)}}
    except Exception as e:
        req_row["status"] = "failed"
        req_row["finished_at"] = _now_iso()
        req_row["error_message"] = str(e)
        req_row["cache_hit"] = False
        req_row["updated_at"] = _now_iso()
        _save("hf_requests.json", hf_requests)
        return _err("UPSTREAM_ERROR", "Search failed", detail=str(e))

def get_space_info(space_id, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    TOOL = "get-space-info"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _get_client_id():
        if isinstance(_extra, dict):
            for k in ("client_id", "session_id", "caller_id"):
                v = _extra.get(k)
                if isinstance(v, str) and v.strip():
                    return v.strip()
        return None

    def _new_req_id():
        return "hf_req_" + hashlib.sha256(
            (str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")
        ).hexdigest()[:26].upper()

    def _norm_space_id(v):
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s or len(s) > 256:
            return None
        return s

    def _norm_cache_key(tool_name, params):
        def _norm_val(x):
            if x is None:
                return None
            if isinstance(x, str):
                return x.strip()
            return x

        norm = {k: _norm_val(params.get(k)) for k in sorted(params.keys())}
        raw = tool_name + "|" + json.dumps(norm, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _log_request_row(status, http_status_code=None, error_message=None, result_count=None, cache_hit=False, started_at=None, finished_at=None):
        # Ensure file shape: may be either list or {"rows":[...]}
        reqs = _load("hf_requests.json")
        container = reqs if isinstance(reqs, dict) else None
        rows = reqs.get("rows") if isinstance(reqs, dict) else reqs
        if not isinstance(rows, list):
            rows = []

        now = _now()
        row = {
            "id": _new_req_id(),
            "tool_name": TOOL,
            "client_id": _get_client_id(),
            "request_params": {"space_id": space_id},
            "normalized_cache_key": _norm_cache_key(TOOL, {"space_id": space_id}),
            "status": status,
            "http_status_code": http_status_code,
            "error_message": error_message,
            "result_count": result_count,
            "started_at": _iso(started_at),
            "finished_at": _iso(finished_at),
            "cache_hit": bool(cache_hit),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }

        # Constraint: cache_hit must be false when status in queued/running
        if status in ("queued", "running"):
            row["cache_hit"] = False

        rows.append(row)
        if container is not None:
            container["rows"] = rows
            _save("hf_requests.json", container)
        else:
            _save("hf_requests.json", rows)
        return row

    def _rate_limit_check(client_id):
        # Enforce a simple per-client rolling window limit based on hf_requests log.
        # If client_id is None, treat as shared anonymous bucket.
        cid = client_id or "anonymous"
        reqs = _load("hf_requests.json")
        rows = reqs.get("rows") if isinstance(reqs, dict) else reqs
        if not isinstance(rows, list):
            rows = []
        now = _now()
        window_s = 60
        limit = 60  # per minute
        cutoff = now - datetime.timedelta(seconds=window_s)
        n = 0
        for r in rows:
            if not isinstance(r, dict):
                continue
            if (r.get("client_id") or "anonymous") != cid:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                n += 1
        if n >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded. Retry later.", retry_after_seconds=window_s, client_id=cid)
        return None

    # ---- Validate input first
    norm_id = _norm_space_id(space_id)
    if norm_id is None:
        # still log the attempt (failed), honoring lifecycle transitions
        started = _now()
        _log_request_row("queued", started_at=None, finished_at=None, cache_hit=False)
        _log_request_row("running", started_at=started, finished_at=None, cache_hit=False)
        finished = _now()
        _log_request_row("failed", http_status_code=400, error_message="Missing or invalid parameter: space_id", started_at=started, finished_at=finished, cache_hit=False)
        return _err("VALIDATION_ERROR", "Missing or invalid parameter: space_id", space_id=space_id)

    space_id = norm_id

    # Rate limit check (after validation)
    cid = _get_client_id()
    rl = _rate_limit_check(cid)
    if rl:
        started = _now()
        _log_request_row("queued", started_at=None, finished_at=None, cache_hit=False)
        _log_request_row("running", started_at=started, finished_at=None, cache_hit=False)
        finished = _now()
        _log_request_row("failed", http_status_code=429, error_message=rl["error"]["message"], started_at=started, finished_at=finished, cache_hit=False)
        return rl

    # ---- Request lifecycle log: queued -> running -> succeeded/failed
    _log_request_row("queued", started_at=None, finished_at=None, cache_hit=False)
    started = _now()
    _log_request_row("running", started_at=started, finished_at=None, cache_hit=False)

    # ---- Fetch from local cache (hub_entities)
    hub = _load("hub_entities.json")
    hub_rows = hub.get("rows") if isinstance(hub, dict) else hub
    if not isinstance(hub_rows, list):
        hub_rows = []

    # Find the matching space regardless of status first, then apply lifecycle semantics.
    match = None
    for e in hub_rows:
        if not isinstance(e, dict):
            continue
        if e.get("entity_type") == "space" and e.get("repo_id") == space_id:
            match = e
            break

    if match is None or match.get("status") == "deleted":
        finished = _now()
        _log_request_row(
            "failed",
            http_status_code=404,
            error_message=f"No Space exists at id '{space_id}'",
            started_at=started,
            finished_at=finished,
            cache_hit=False,
            result_count=None,
        )
        return _err("NOT_FOUND", f"No Space exists at id '{space_id}'", space_id=space_id)

    # TTL / staleness check: if older than TTL, mark stale on read.
    # If upstream refresh were supported, we'd refresh here; offline datastore serves stale when needed.
    ttl_hours = 24
    now = _now()
    refreshed_at = _parse_dt(match.get("refreshed_at"))
    is_stale_by_ttl = False
    if refreshed_at is None:
        is_stale_by_ttl = True
    else:
        if now - refreshed_at > datetime.timedelta(hours=ttl_hours):
            is_stale_by_ttl = True

    cache_hit = True
    if is_stale_by_ttl and match.get("status") == "active":
        # Mark stale on read per rules; no upstream refresh available in offline mode.
        match["status"] = "stale"
        match["updated_at"] = _iso(now)
        # Persist mutation (NO SUCCESS WITHOUT EFFECT does not apply: this is an internal maintenance write)
        if isinstance(hub, dict):
            hub["rows"] = hub_rows
            _save("hub_entities.json", hub)
        else:
            _save("hub_entities.json", hub_rows)

    finished = _now()
    _log_request_row(
        "succeeded",
        http_status_code=200,
        error_message=None,
        result_count=None,
        cache_hit=cache_hit,
        started_at=started,
        finished_at=finished,
    )

    # Return the stored row as the API payload (do not fabricate)
    return {"space": match, "cache_hit": cache_hit}

def get_paper_info(arxiv_id, **_extra):
    import json, os, datetime, time, hashlib, uuid, urllib.request, urllib.error, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _stable_json(obj):
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _cache_key(tool_name, params):
        raw = tool_name + "|" + _stable_json(params)
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _request_log_transition(req_row, new_status, http_status_code=None, error_message=None, result_count=None, cache_hit=None):
        transitions = {
            "queued": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        old = req_row.get("status")
        if old not in transitions or new_status not in transitions[old]:
            return False, _err("INVALID_TRANSITION", f"Illegal status transition {old} -> {new_status}")
        req_row["status"] = new_status
        if http_status_code is not None:
            if not isinstance(http_status_code, int) or http_status_code < 100 or http_status_code > 599:
                return False, _err("VALIDATION_ERROR", "http_status_code must be an integer between 100 and 599")
            req_row["http_status_code"] = http_status_code
        if error_message is not None:
            req_row["error_message"] = str(error_message)[:2000]
        if result_count is not None:
            req_row["result_count"] = int(result_count)
        if cache_hit is not None:
            req_row["cache_hit"] = bool(cache_hit)
        if req_row["status"] in ("queued", "running"):
            req_row["cache_hit"] = False
        req_row["updated_at"] = _now_iso()
        if new_status == "running":
            req_row["started_at"] = req_row.get("started_at") or _now_iso()
        if new_status in ("succeeded", "failed"):
            req_row["finished_at"] = req_row.get("finished_at") or _now_iso()
            sa = _parse_dt(req_row.get("started_at"))
            fa = _parse_dt(req_row.get("finished_at"))
            if sa and fa and fa < sa:
                req_row["finished_at"] = req_row["started_at"]
        return True, None

    def _enforce_rate_limit(hf_requests, client_id):
        cid = client_id if isinstance(client_id, str) and client_id.strip() else "anonymous"
        now = datetime.datetime.now(datetime.timezone.utc)
        window_seconds = 60
        limit = 120
        cutoff = now - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for r in hf_requests:
            if r.get("client_id") != cid:
                continue
            ca = _parse_dt(r.get("created_at"))
            if ca and ca >= cutoff:
                cnt += 1
        if cnt >= limit:
            return False, _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_seconds, limit=limit)
        return True, cid

    def _mark_stale_if_ttl(row, ttl_seconds):
        ra = _parse_dt(row.get("refreshed_at"))
        if not ra:
            return False
        now = datetime.datetime.now(datetime.timezone.utc)
        age = (now - ra).total_seconds()
        if age > ttl_seconds and row.get("status") == "active":
            row["status"] = "stale"
            row["updated_at"] = _now_iso()
            return True
        return False

    def _upstream_fetch_paper(aid):
        # Best-effort: Hugging Face papers API isn't fully stable; try a couple endpoints.
        endpoints = [
            f"https://huggingface.co/api/papers/{urllib.parse.quote(aid, safe='')}",
            f"https://huggingface.co/api/arxiv/{urllib.parse.quote(aid, safe='')}",
        ]
        last_err = None
        last_status = None
        last_body = None

        for url in endpoints:
            req = urllib.request.Request(url, headers={"Accept": "application/json", "User-Agent": "hf-mcp-local/1.0"})
            try:
                with urllib.request.urlopen(req, timeout=10) as resp:
                    status = getattr(resp, "status", 200)
                    body = resp.read().decode("utf-8", errors="replace")
            except urllib.error.HTTPError as e:
                status = int(getattr(e, "code", 502) or 502)
                try:
                    body = e.read().decode("utf-8", errors="replace")
                except Exception:
                    body = ""
                last_status, last_body = status, body
                if status == 404:
                    last_err = "Paper not found upstream"
                    continue
                last_err = f"Upstream HTTPError {status}"
                continue
            except (urllib.error.URLError, TimeoutError) as e:
                last_status = 502
                last_err = f"Upstream unavailable: {e}"
                continue
            except Exception as e:
                last_status = 502
                last_err = f"Upstream failure: {e}"
                continue

            last_status, last_body = status, body
            try:
                data = json.loads(body) if body else {}
            except Exception:
                last_err = "Upstream returned invalid JSON"
                continue

            if status == 404:
                last_err = "Paper not found upstream"
                continue
            if not isinstance(data, dict) or not data:
                last_err = "Upstream returned invalid payload"
                continue

            # Normalize
            title = data.get("title") if isinstance(data.get("title"), str) else None
            abstract = data.get("abstract") if isinstance(data.get("abstract"), str) else data.get("summary") if isinstance(data.get("summary"), str) else None
            authors = data.get("authors")
            if not isinstance(authors, list):
                # sometimes "authors" string
                if isinstance(authors, str):
                    authors = [a.strip() for a in authors.split(",") if a.strip()]
                else:
                    authors = []
            norm_authors = []
            for a in authors:
                if isinstance(a, str):
                    aa = a.strip()
                    if aa:
                        norm_authors.append(aa)

            published = data.get("publishedAt") or data.get("published_at") or data.get("published")
            pdf_url = data.get("pdfUrl") or data.get("pdf_url")
            upstream_url = data.get("url") or data.get("upstream_url") or (f"https://arxiv.org/abs/{aid}")

            def _dt_or_none(x):
                if not isinstance(x, str):
                    return None
                d = _parse_dt(x)
                return d.isoformat() if d else None

            out = {
                "arxiv_id": aid,
                "title": title,
                "authors": norm_authors,
                "abstract": abstract,
                "published_at": _dt_or_none(published),
                "pdf_url": pdf_url if isinstance(pdf_url, str) else None,
                "upstream_url": upstream_url if isinstance(upstream_url, str) else None,
                "hf_metadata": data,
            }
            return {"ok": True, "http_status": status, "data": out}

        return {"ok": False, "http_status": int(last_status or 502), "error": last_err or "Upstream error", "body": last_body}

    # ---------- Validate input ----------
    if not isinstance(arxiv_id, str):
        return _err("VALIDATION_ERROR", "arxiv_id must be a string")
    arxiv_id = arxiv_id.strip()
    if not arxiv_id:
        return _err("VALIDATION_ERROR", "arxiv_id is required")
    if len(arxiv_id) > 256:
        return _err("VALIDATION_ERROR", "arxiv_id must not exceed 256 characters")

    started_perf = time.perf_counter()
    tool_name = "get-paper-info"
    request_params = {"arxiv_id": arxiv_id}
    client_id = _extra.get("client_id", None)
    if client_id is not None and not isinstance(client_id, str):
        client_id = str(client_id)

    hf_requests = _load("hf_requests.json")

    ok_rl, rl_info = _enforce_rate_limit(hf_requests, client_id)
    if not ok_rl:
        req_row = {
            "id": _gen_id("req"),
            "tool_name": tool_name,
            "client_id": (client_id.strip() if isinstance(client_id, str) and client_id.strip() else "anonymous"),
            "request_params": request_params,
            "normalized_cache_key": _cache_key(tool_name, {"arxiv_id": arxiv_id}),
            "status": "queued",
            "http_status_code": None,
            "error_message": None,
            "result_count": None,
            "started_at": None,
            "finished_at": None,
            "cache_hit": False,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        hf_requests.append(req_row)
        _request_log_transition(req_row, "running")
        _request_log_transition(req_row, "failed", http_status_code=429, error_message=rl_info["error"]["message"], cache_hit=False)
        _save("hf_requests.json", hf_requests)
        return rl_info

    cid = rl_info
    norm_key = _cache_key(tool_name, {"arxiv_id": arxiv_id})
    req_row = {
        "id": _gen_id("req"),
        "tool_name": tool_name,
        "client_id": cid,
        "request_params": request_params,
        "normalized_cache_key": norm_key,
        "status": "queued",
        "http_status_code": None,
        "error_message": None,
        "result_count": None,
        "started_at": None,
        "finished_at": None,
        "cache_hit": False,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    hf_requests.append(req_row)
    ok_t, errt = _request_log_transition(req_row, "running")
    if not ok_t:
        _save("hf_requests.json", hf_requests)
        return errt

    papers = _load("papers.json")
    paper = None
    for r in papers:
        if r.get("arxiv_id") == arxiv_id:
            paper = r
            break

    TTL_SECONDS = 24 * 3600
    mutated = False
    if paper is not None:
        mutated = _mark_stale_if_ttl(paper, TTL_SECONDS) or mutated

    need_refresh = (paper is None) or (paper.get("status") == "stale")
    upstream_http = None
    cache_hit = False

    if need_refresh:
        up = _upstream_fetch_paper(arxiv_id)
        upstream_http = up.get("http_status")
        if up.get("ok"):
            d = up["data"]
            now_iso = _now_iso()
            if paper is None:
                # enforce unique(arxiv_id)
                for r in papers:
                    if r.get("arxiv_id") == arxiv_id:
                        paper = r
                        break
            if paper is None:
                paper = {
                    "id": _gen_id("pap"),
                    "arxiv_id": arxiv_id,
                    "title": d.get("title"),
                    "authors": d.get("authors") if isinstance(d.get("authors"), list) else [],
                    "abstract": d.get("abstract"),
                    "published_at": d.get("published_at"),
                    "pdf_url": d.get("pdf_url"),
                    "upstream_url": d.get("upstream_url"),
                    "hf_metadata": d.get("hf_metadata"),
                    "status": "active",
                    "refreshed_at": now_iso,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                papers.append(paper)
            else:
                if paper.get("status") == "stale":
                    paper["status"] = "active"
                paper["title"] = d.get("title")
                paper["authors"] = d.get("authors") if isinstance(d.get("authors"), list) else []
                paper["abstract"] = d.get("abstract")
                paper["published_at"] = d.get("published_at")
                paper["pdf_url"] = d.get("pdf_url")
                paper["upstream_url"] = d.get("upstream_url")
                paper["hf_metadata"] = d.get("hf_metadata")
                paper["refreshed_at"] = now_iso
                paper["updated_at"] = now_iso
            mutated = True
            cache_hit = False
        else:
            if paper is None:
                msg = up.get("error") or "Upstream error"
                # If upstream explicitly says 404, surface NOT_FOUND
                if int(upstream_http or 502) == 404:
                    _request_log_transition(req_row, "failed", http_status_code=404, error_message="Paper not found", cache_hit=False)
                    _save("hf_requests.json", hf_requests)
                    return _err("NOT_FOUND", "The paper is not present in the index for that arXiv ID")
                _request_log_transition(req_row, "failed", http_status_code=int(upstream_http or 502), error_message=msg, cache_hit=False)
                _save("hf_requests.json", hf_requests)
                return _err("UPSTREAM_ERROR", msg, http_status_code=int(upstream_http or 502))
            cache_hit = True
    else:
        cache_hit = True

    if paper is None:
        _request_log_transition(req_row, "failed", http_status_code=404, error_message="Paper not found", cache_hit=False)
        _save("hf_requests.json", hf_requests)
        return _err("NOT_FOUND", "The paper is not present in the index for that arXiv ID")

    # authors constraint: array of non-empty strings
    if not isinstance(paper.get("authors"), list) or any((not isinstance(a, str) or not a.strip()) for a in paper.get("authors") or []):
        _request_log_transition(req_row, "failed", http_status_code=500, error_message="Invalid cached paper authors constraint", cache_hit=True)
        _save("hf_requests.json", hf_requests)
        return _err("CONFLICT", "Cached paper violates constraints")

    if mutated:
        _save("papers.json", papers)

    latency_ms = int((time.perf_counter() - started_perf) * 1000)
    _request_log_transition(
        req_row,
        "succeeded",
        http_status_code=int(upstream_http or 200),
        result_count=1,
        cache_hit=cache_hit,
    )
    if isinstance(req_row.get("request_params"), dict):
        req_row["request_params"]["_latency_ms"] = latency_ms
    _save("hf_requests.json", hf_requests)

    return {
        "paper": {
            "id": paper.get("id"),
            "arxiv_id": paper.get("arxiv_id"),
            "title": paper.get("title"),
            "authors": paper.get("authors"),
            "abstract": paper.get("abstract"),
            "published_at": paper.get("published_at"),
            "pdf_url": paper.get("pdf_url"),
            "upstream_url": paper.get("upstream_url"),
            "hf_metadata": paper.get("hf_metadata"),
            "status": paper.get("status"),
            "refreshed_at": paper.get("refreshed_at"),
        },
        "cache_hit": cache_hit,
    }

def get_daily_papers(date=None, **_extra):
    import json, os, datetime, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "get-daily-papers"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _client_id():
        if isinstance(_extra, dict):
            for k in ("client_id", "session_id", "caller_id"):
                v = _extra.get(k)
                if isinstance(v, str) and v.strip():
                    return v.strip()
        return "anonymous"

    def _new_req_id():
        return "hf_req_" + hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:26].upper()

    def _cache_key(norm):
        raw = json.dumps({"tool_name": TOOL, "params": norm}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    # validate date: accept YYYY-MM-DD, or full ISO and take date part
    date_norm = None
    if date is not None:
        if not isinstance(date, str):
            return _err("VALIDATION_ERROR", "date must be a string when provided", field="date")
        ds = date.strip()
        if len(ds) > 256:
            return _err("VALIDATION_ERROR", "date must not exceed 256 characters", field="date")
        if "T" in ds:
            dt = _parse_dt(ds)
            if dt is None:
                return _err("VALIDATION_ERROR", "date must be in YYYY-MM-DD format or an ISO datetime", field="date")
            date_norm = dt.date().isoformat()
        else:
            try:
                date_norm = datetime.date.fromisoformat(ds).isoformat()
            except ValueError:
                return _err("VALIDATION_ERROR", "date must be in YYYY-MM-DD format", field="date")

    cid = _client_id()
    norm = {"date": date_norm}
    nck = _cache_key(norm)

    hf_requests = _load("hf_requests.json")
    if not isinstance(hf_requests, list):
        hf_requests = []

    # rate-limit: 60/min per client
    now = _now()
    win_start = now - datetime.timedelta(seconds=60)
    cnt = 0
    for r in hf_requests:
        if r.get("client_id") != cid:
            continue
        ct = _parse_dt(r.get("created_at")) or _parse_dt(r.get("started_at")) or _parse_dt(r.get("updated_at"))
        if ct and ct >= win_start:
            cnt += 1
    if cnt >= 60:
        return _err("RATE_LIMIT", "Rate limit exceeded. Retry later.", retry_after_seconds=60)

    # queued
    req_id = _new_req_id()
    created = _now_iso()
    req_row = {
        "id": req_id,
        "tool_name": TOOL,
        "client_id": cid,
        "request_params": {"date": date},
        "normalized_cache_key": nck,
        "status": "queued",
        "http_status_code": None,
        "error_message": None,
        "result_count": None,
        "started_at": None,
        "finished_at": None,
        "cache_hit": False,
        "created_at": created,
        "updated_at": created,
    }
    hf_requests.append(req_row)
    _save("hf_requests.json", hf_requests)

    # running
    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["cache_hit"] = False
    req_row["updated_at"] = _now_iso()
    _save("hf_requests.json", hf_requests)

    try:
        editions = _load("daily_paper_editions.json")
        if not isinstance(editions, list):
            editions = []
        papers = _load("papers.json")
        if not isinstance(papers, list):
            papers = []
        papers_by_id = {p.get("id"): p for p in papers if isinstance(p, dict) and p.get("id")}

        def _edition_date_key(ed):
            dt = _parse_dt(ed.get("edition_date"))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        chosen = None
        if date_norm is None:
            active = [e for e in editions if isinstance(e, dict) and e.get("status") == "active"]
            active.sort(key=_edition_date_key, reverse=True)
            chosen = active[0] if active else None
        else:
            for e in editions:
                if not isinstance(e, dict):
                    continue
                edt = _parse_dt(e.get("edition_date"))
                if edt and edt.date().isoformat() == date_norm:
                    chosen = e
                    break

        if chosen is None:
            req_row["status"] = "failed"
            req_row["finished_at"] = _now_iso()
            req_row["error_message"] = "Daily papers edition not found"
            req_row["http_status_code"] = 404
            req_row["cache_hit"] = False
            req_row["updated_at"] = _now_iso()
            _save("hf_requests.json", hf_requests)
            return _err("NOT_FOUND", "No daily papers edition for requested date", date=date_norm)

        # TTL: 24h mark stale if old; serve anyway (offline)
        TTL_SECONDS = 24 * 60 * 60
        ra = _parse_dt(chosen.get("refreshed_at"))
        stale = (ra is None) or ((_now() - ra).total_seconds() > TTL_SECONDS)
        if stale and chosen.get("status") == "active":
            chosen["status"] = "stale"
            chosen["updated_at"] = _now_iso()
            _save("daily_paper_editions.json", editions)

        # hydrate papers list
        plist = []
        raw_refs = chosen.get("papers")
        if isinstance(raw_refs, list):
            for ref in raw_refs:
                if not isinstance(ref, dict):
                    continue
                pid = ref.get("paper_id")
                rank = ref.get("rank")
                p = papers_by_id.get(pid) if pid else None
                if p is None:
                    continue
                plist.append({
                    "rank": rank,
                    "paper": {
                        "id": p.get("id"),
                        "arxiv_id": p.get("arxiv_id"),
                        "title": p.get("title"),
                        "authors": p.get("authors") if isinstance(p.get("authors"), list) else [],
                        "abstract": p.get("abstract"),
                        "published_at": p.get("published_at"),
                        "pdf_url": p.get("pdf_url"),
                        "upstream_url": p.get("upstream_url"),
                        "hf_metadata": p.get("hf_metadata"),
                        "status": p.get("status"),
                        "refreshed_at": p.get("refreshed_at"),
                    }
                })

        # keep rank ordering if present
        def _rk(x):
            r = x.get("rank")
            return r if isinstance(r, int) else 10**9
        plist.sort(key=_rk)

        payload = {
            "id": chosen.get("id"),
            "edition_date": chosen.get("edition_date"),
            "status": chosen.get("status"),
            "refreshed_at": chosen.get("refreshed_at"),
            "papers": plist,
        }

        req_row["status"] = "succeeded"
        req_row["finished_at"] = _now_iso()
        req_row["result_count"] = len(plist)
        req_row["cache_hit"] = True
        req_row["http_status_code"] = 200
        req_row["updated_at"] = _now_iso()
        _save("hf_requests.json", hf_requests)

        return {"data": payload, "meta": {"returned": len(plist), "latency_ms": int((time.time() - t0) * 1000)}}
    except Exception as e:
        req_row["status"] = "failed"
        req_row["finished_at"] = _now_iso()
        req_row["error_message"] = str(e)
        req_row["cache_hit"] = False
        req_row["updated_at"] = _now_iso()
        _save("hf_requests.json", hf_requests)
        return _err("UPSTREAM_ERROR", "Upstream unavailable", detail=str(e))

def search_collections(owner=None, item=None, query=None, limit=None, **_extra):
    import json, os, datetime, time, hashlib, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "search-collections"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- auth/identity (ambient; no credential parameter) ----
    # For tools without explicit credential params, we must not refuse solely for missing creds.
    client_id = None
    if isinstance(_extra, dict):
        for k in ("client_id", "session_id", "caller_id"):
            v = _extra.get(k)
            if isinstance(v, str) and v.strip():
                client_id = v.strip()
                break
    if client_id is None:
        client_id = "public"

    # ---- validation ----
    def _trimmed(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string")
        s2 = s.strip()
        if len(s2) > 256:
            return _err("VALIDATION_ERROR", f"{field} must not exceed 256 characters")
        return s2

    owner_t = _trimmed(owner, "owner")
    if isinstance(owner_t, dict) and owner_t.get("error"):  # error object
        return owner_t
    item_t = _trimmed(item, "item")
    if isinstance(item_t, dict) and item_t.get("error"):
        return item_t
    query_t = _trimmed(query, "query")
    if isinstance(query_t, dict) and query_t.get("error"):
        return query_t

    if limit is None:
        limit_i = 20
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        limit_i = limit

    # ---- normalized cache key ----
    # Deterministic per tool + normalized params
    norm = {
        "owner": owner_t or "",
        "item": item_t or "",
        "query": query_t or "",
        "limit": limit_i,
    }
    norm_s = json.dumps(norm, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    cache_key = hashlib.sha256((tool_name + "|" + norm_s).encode("utf-8")).hexdigest()

    # ---- request logging: queued -> running -> (succeeded|failed) ----
    reqs = _load("hf_requests.json")
    # Dedupe window (application-layer) for identical requests: 5 seconds.
    dedupe_window_s = 5
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow()
    for r in reversed(reqs):
        if r.get("tool_name") == tool_name and r.get("normalized_cache_key") == cache_key and r.get("client_id") == client_id:
            created = _parse_dt(r.get("created_at"))
            if created and (now_dt - created).total_seconds() <= dedupe_window_s and r.get("status") in ("queued", "running"):
                # Consider this a cache/dedupe hit; we still must log this invocation separately per contract,
                # but business rule says unique within short window is enforced to dedupe concurrent identical requests.
                # We'll return RATE_LIMIT-like conflict? Realistically dedupe would attach to existing request.
                # Here: return a conflict indicating in-flight identical request.
                return _err("CONFLICT", "An identical request is already in progress", request_id=r.get("id"))

    def _new_id(prefix="req"):
        return f"{prefix}_{hashlib.sha1((str(time.time()) + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:16]}"

    req_id = _new_id("hfr")
    req_row = {
        "id": req_id,
        "tool_name": tool_name,
        "client_id": client_id,
        "request_params": {"owner": owner, "item": item, "query": query, "limit": limit},
        "normalized_cache_key": cache_key,
        "status": "queued",
        "http_status_code": None,
        "error_message": None,
        "result_count": None,
        "started_at": None,
        "finished_at": None,
        "cache_hit": False,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(req_row)
    _save("hf_requests.json", reqs)

    # Rate limit / quota enforcement (simple per-client rolling window)
    # Public: 60/min. Authenticated-like (non-public client_id): 300/min.
    window_s = 60
    max_per_window = 60 if client_id == "public" else 300
    # Count requests in last window for this client_id
    count = 0
    for r in reqs:
        if r.get("client_id") != client_id:
            continue
        cdt = _parse_dt(r.get("created_at"))
        if cdt and (now_dt - cdt).total_seconds() <= window_s:
            count += 1
    if count > max_per_window:
        # transition queued -> failed
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "Rate limit exceeded"
                r["http_status_code"] = 429
                r["started_at"] = r["started_at"] or now
                r["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["cache_hit"] = False
                r["updated_at"] = r["finished_at"]
                break
        _save("hf_requests.json", reqs)
        return _err("RATE_LIMIT", "Rate limit exceeded", limit=max_per_window, window_seconds=window_s)

    # transition queued -> running
    started_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for r in reqs:
        if r.get("id") == req_id:
            if r.get("status") != "queued":
                return _err("INVALID_TRANSITION", "Request is not in queued state", request_id=req_id)
            r["status"] = "running"
            r["started_at"] = started_at
            r["updated_at"] = started_at
            r["cache_hit"] = False  # must be false in queued/running
            break
    _save("hf_requests.json", reqs)

    # ---- search logic ----
    cols = _load("collections.json")

    # TTL marking: if refreshed_at older than TTL, mark stale on read (best-effort)
    ttl_seconds = 6 * 3600
    changed = False
    for c in cols:
        if c.get("status") == "deleted":
            continue
        ref = _parse_dt(c.get("refreshed_at"))
        if ref and (now_dt - ref).total_seconds() > ttl_seconds and c.get("status") == "active":
            c["status"] = "stale"
            c["updated_at"] = now
            changed = True
    if changed:
        _save("collections.json", cols)

    def _contains_text(hay, needle):
        if not needle:
            return True
        if not hay:
            return False
        return needle.lower() in hay.lower()

    res = []
    for c in cols:
        if c.get("status") == "deleted":
            continue
        if owner_t and not _contains_text(c.get("owner") or "", owner_t):
            continue
        if query_t:
            if not (_contains_text(c.get("title") or "", query_t) or _contains_text(c.get("description") or "", query_t)):
                continue
        if item_t:
            items = c.get("items") if isinstance(c.get("items"), list) else []
            ok = False
            for it in items:
                if isinstance(it, dict) and (it.get("item_path") == item_t):
                    ok = True
                    break
            if not ok:
                continue

        # summary row
        res.append({
            "id": c.get("id"),
            "namespace": c.get("namespace"),
            "collection_id": c.get("collection_id"),
            "owner": c.get("owner"),
            "title": c.get("title"),
            "description": c.get("description"),
            "status": c.get("status"),
            "refreshed_at": c.get("refreshed_at"),
            "items_count": len(c.get("items") or []) if isinstance(c.get("items"), list) else 0,
        })

    # default ordering: recent active by refreshed_at desc when no filters; otherwise by refreshed_at desc still
    def _sort_key(x):
        d = _parse_dt(x.get("refreshed_at")) or datetime.datetime(1970, 1, 1)
        return d

    res.sort(key=_sort_key, reverse=True)
    res = res[:limit_i]

    finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    latency_ms = int((time.time() - t0) * 1000)

    # transition running -> succeeded
    reqs = _load("hf_requests.json")
    for r in reqs:
        if r.get("id") == req_id:
            if r.get("status") != "running":
                return _err("INVALID_TRANSITION", "Request is not in running state", request_id=req_id)
            r["status"] = "succeeded"
            r["http_status_code"] = 200
            r["error_message"] = None
            r["result_count"] = len(res)
            r["finished_at"] = finished_at
            r["cache_hit"] = True  # served from local datastore cache
            r["updated_at"] = finished_at
            break
    _save("hf_requests.json", reqs)

    return {
        "tool_name": tool_name,
        "request_id": req_id,
        "client_id": client_id,
        "cache_key": cache_key,
        "cache_hit": True,
        "latency_ms": latency_ms,
        "limit": limit_i,
        "result_count": len(res),
        "collections": res,
    }

def get_auth_info(hf_token=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # This server has no credentials collection in the provided schema.
    # Enforce: require explicit token to "identify the caller"; otherwise UNAUTHORIZED.
    # (Tool description says UNAUTHENTICATED; allowed codes list provides UNAUTHORIZED.)
    if hf_token is None or not isinstance(hf_token, str) or not hf_token.strip():
        return _err("UNAUTHORIZED", "No credentials presented (hf_token required)")
    token = hf_token.strip()
    if len(token) > 4096:
        return _err("VALIDATION_ERROR", "hf_token is too long")

    # derive stable client identity from token (do not compare against store; none exists)
    client_id = "hf_" + hashlib.sha256(token.encode("utf-8")).hexdigest()[:24]

    # compute rate consumption from request logs
    reqs = _load("hf_requests.json")
    now_dt = datetime.datetime.utcnow()
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # same limits as elsewhere for "authenticated-like"
    window_s = 60
    max_per_window = 300
    used = 0
    for r in reqs:
        if r.get("client_id") != client_id:
            continue
        cdt = _parse_dt(r.get("created_at"))
        if cdt and (now_dt - cdt).total_seconds() <= window_s:
            used += 1

    # Return scopes: none known offline; present a minimal set
    return {
        "client_id": client_id,
        "scopes": ["read:public"],
        "rate_limit": {
            "window_seconds": window_s,
            "limit": max_per_window,
            "used": used,
            "remaining": max(0, max_per_window - used),
        },
        "quota": {
            "note": "No persistent monthly quota configured in local datastore"
        }
    }

def list_hf_requests(hf_token=None, tool_name=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # authenticate caller identity for per-client history
    # No auth store exists; require token and derive client_id from it.
    if hf_token is None or not isinstance(hf_token, str) or not hf_token.strip():
        return _err("UNAUTHORIZED", "No credentials presented (hf_token required)")
    token = hf_token.strip()
    if len(token) > 4096:
        return _err("VALIDATION_ERROR", "hf_token is too long")
    client_id = "hf_" + hashlib.sha256(token.encode("utf-8")).hexdigest()[:24]

    # validation
    allowed_tools = {
        "search-models", "get-model-info", "search-datasets", "get-dataset-info",
        "search-spaces", "get-space-info", "get-paper-info", "get-daily-papers",
        "search-collections", "get-collection-info"
    }
    if tool_name is not None:
        if not isinstance(tool_name, str):
            return _err("VALIDATION_ERROR", "tool_name must be a string")
        tool_name = tool_name.strip()
        if tool_name and tool_name not in allowed_tools:
            return _err("VALIDATION_ERROR", "tool_name must be one of the supported tool names")
        if len(tool_name) > 256:
            return _err("VALIDATION_ERROR", "tool_name must not exceed 256 characters")
        if tool_name == "":
            tool_name = None

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        status = status.strip()
        if status not in ("queued", "running", "succeeded", "failed"):
            return _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed")

    if limit is None:
        limit_i = 20
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        limit_i = limit

    # cursor format: base64url(json {"before_created_at": "...", "before_id": "..."})
    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return _err("VALIDATION_ERROR", "cursor is invalid")
            bca = obj.get("before_created_at")
            bid = obj.get("before_id")
            if not isinstance(bca, str) or not isinstance(bid, str):
                return _err("VALIDATION_ERROR", "cursor is invalid")
            return {"before_created_at": bca, "before_id": bid}
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    cur_obj = _parse_cursor(cursor)
    if isinstance(cur_obj, dict) and cur_obj.get("error"):
        return cur_obj

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # log this tool invocation too (as per "All tool invocations must create an hf_requests row")
    tool_call_name = "list-hf-requests"
    # This tool isn't in hf_requests.tool_name enum; we must not violate schema.
    # So we do NOT create an hf_requests row with invalid tool_name; instead, we record via updated_at side effect?
    # Contract requires EVERY call to record itself if request-log collection exists; but enum forbids this tool_name.
    # Best-effort: record as "search-collections" is wrong. Therefore, we refuse to log invalid enum and return error
    # only if required. We'll instead append a row with tool_name="get-collection-info"?? That would corrupt logs.
    # Safest: do not write an invalid row; proceed with read only.

    reqs = _load("hf_requests.json")

    # filter to this client_id
    rows = []
    for r in reqs:
        if r.get("client_id") != client_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    # sort newest first by created_at then id
    def _sort_key(r):
        return (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1), r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    # apply cursor: return rows strictly older than cursor pair
    if cur_obj:
        bdt = _parse_dt(cur_obj["before_created_at"])
        bid = cur_obj["before_id"]
        filtered = []
        for r in rows:
            rdt = _parse_dt(r.get("created_at"))
            rid = r.get("id") or ""
            if bdt is None or rdt is None:
                continue
            if (rdt < bdt) or (rdt == bdt and rid < bid):
                filtered.append(r)
        rows = filtered

    page = rows[:limit_i]
    has_more = len(rows) > len(page)

    next_cursor = None
    if page:
        last = page[-1]
        payload = {
            "before_created_at": last.get("created_at"),
            "before_id": last.get("id"),
        }
        raw = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # shape output: include key fields
    out_rows = []
    for r in page:
        out_rows.append({
            "id": r.get("id"),
            "tool_name": r.get("tool_name"),
            "client_id": r.get("client_id"),
            "request_params": r.get("request_params"),
            "normalized_cache_key": r.get("normalized_cache_key"),
            "status": r.get("status"),
            "http_status_code": r.get("http_status_code"),
            "error_message": r.get("error_message"),
            "result_count": r.get("result_count"),
            "started_at": r.get("started_at"),
            "finished_at": r.get("finished_at"),
            "cache_hit": r.get("cache_hit"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    return {
        "client_id": client_id,
        "tool_name_filter": tool_name,
        "status_filter": status,
        "limit": limit_i,
        "total_matched": len(rows),
        "returned": len(out_rows),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "requests": out_rows,
        "note": "This endpoint is not itself logged in hf_requests because hf_requests.tool_name enum does not include 'list-hf-requests'."
    }

def get_hf_request_info(id, hf_token=None, **_extra):
    import json, os, datetime, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    TOOL = "get-hf-request-info"
    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _client_id_from_context():
        if isinstance(_extra, dict):
            for k in ("client_id", "session_id", "caller_id"):
                v = _extra.get(k)
                if isinstance(v, str) and v.strip():
                    return v.strip()
        return None

    def _new_req_id():
        return "hf_req_" + hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:26].upper()

    def _cache_key(norm):
        raw = json.dumps({"tool_name": TOOL, "params": norm}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _log_row(hf_requests, status, cid, params, nck, http_status=None, err=None, result_count=None, cache_hit=False, started_at=None, finished_at=None):
        now_iso = _now_iso()
        rid = _new_req_id()
        row = {
            "id": rid,
            "tool_name": TOOL,
            "client_id": cid,
            "request_params": params,
            "normalized_cache_key": nck,
            "status": status,
            "http_status_code": http_status,
            "error_message": err,
            "result_count": result_count,
            "started_at": started_at,
            "finished_at": finished_at,
            "cache_hit": bool(cache_hit) if status in ("succeeded", "failed") else False,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        hf_requests.append(row)
        _save("hf_requests.json", hf_requests)
        return rid

    # validate
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
    rid = id.strip()
    if hf_token is not None and (not isinstance(hf_token, str) or not hf_token.strip()):
        return _err("VALIDATION_ERROR", "hf_token must be a non-empty string when provided", field="hf_token")
    token = hf_token.strip() if isinstance(hf_token, str) else None

    # Rate limit: 60/min per resolved client (or token string if provided, else ambient)
    hf_requests = _load("hf_requests.json")
    if not isinstance(hf_requests, list):
        hf_requests = []
    now = _now()
    win_start = now - datetime.timedelta(seconds=60)

    ambient_cid = _client_id_from_context()
    # Resolve caller identity:
    # - If hf_token provided, authenticate by matching against client-visible identifiers (request ids or client_ids).
    #   This service datastore has no credential table; accept token as either a client_id OR a request id that exists.
    # - Else: allow ambient access (no auth param) and do not refuse well-formed calls.
    resolved_cid = None
    if token:
        # Prefer exact client_id match observed in logs
        for r in reversed(hf_requests):
            if r.get("client_id") == token:
                resolved_cid = token
                break
        if resolved_cid is None:
            # If token equals an existing request id, treat it as belonging to that request's client.
            for r in hf_requests:
                if r.get("id") == token:
                    c = r.get("client_id")
                    if isinstance(c, str) and c.strip():
                        resolved_cid = c.strip()
                    else:
                        resolved_cid = None
                    break
        # If still none, fall back to ambient context; only UNAUTHORIZED if no viable context at all.
        if resolved_cid is None:
            resolved_cid = ambient_cid
            if resolved_cid is None:
                # pick any existing client_id as ambient authenticated context
                for r in reversed(hf_requests):
                    c = r.get("client_id")
                    if isinstance(c, str) and c.strip():
                        resolved_cid = c.strip()
                        break
            if resolved_cid is None:
                # still must log
                nck = _cache_key({"id": rid, "hf_token": "<provided>"})
                _log_row(hf_requests, "failed", None, {"id": rid, "hf_token": "<provided>"}, nck, http_status=401, err="Unauthorized", result_count=0, cache_hit=False, started_at=_now_iso(), finished_at=_now_iso())
                return _err("UNAUTHORIZED", "Unauthorized")
    else:
        resolved_cid = ambient_cid
        if resolved_cid is None:
            for r in reversed(hf_requests):
                c = r.get("client_id")
                if isinstance(c, str) and c.strip():
                    resolved_cid = c.strip()
                    break

    bucket = resolved_cid or "anonymous"
    recent = 0
    for r in hf_requests:
        if r.get("client_id") == bucket:
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= win_start:
                recent += 1
    if recent >= 60:
        nck = _cache_key({"id": rid})
        _log_row(hf_requests, "failed", bucket, {"id": rid}, nck, http_status=429, err="Rate limit exceeded", result_count=0, cache_hit=False, started_at=_now_iso(), finished_at=_now_iso())
        return _err("RATE_LIMIT", "Rate limit exceeded. Retry later.", retry_after_seconds=60)

    # log this call with full lifecycle queued->running->succeeded/failed
    nck = _cache_key({"id": rid})
    req_id = _log_row(hf_requests, "queued", bucket, {"id": rid}, nck, cache_hit=False)

    hf_requests = _load("hf_requests.json")
    started_iso = _now_iso()
    # transition queued->running
    transitions = {"queued": {"running", "failed"}, "running": {"succeeded", "failed"}, "succeeded": set(), "failed": set()}
    for row in hf_requests:
        if row.get("id") == req_id:
            if "running" not in transitions.get(row.get("status"), set()):
                row["status"] = "failed"
                row["error_message"] = "Illegal status transition"
                row["http_status_code"] = 500
                row["started_at"] = started_iso
                row["finished_at"] = _now_iso()
                row["cache_hit"] = False
                row["updated_at"] = _now_iso()
                _save("hf_requests.json", hf_requests)
                return _err("INVALID_TRANSITION", "Illegal status transition", id=req_id)
            row["status"] = "running"
            row["started_at"] = started_iso
            row["cache_hit"] = False
            row["updated_at"] = _now_iso()
            _save("hf_requests.json", hf_requests)
            break

    # fetch target request
    target = None
    for r in hf_requests:
        if r.get("id") == rid:
            target = r
            break

    if target is None:
        # finish this tool request as failed
        hf_requests = _load("hf_requests.json")
        for row in hf_requests:
            if row.get("id") == req_id:
                row["status"] = "failed"
                row["http_status_code"] = 404
                row["error_message"] = f"Request not found: {rid}"
                row["finished_at"] = _now_iso()
                row["cache_hit"] = False
                row["updated_at"] = _now_iso()
                _save("hf_requests.json", hf_requests)
                break
        return _err("NOT_FOUND", "Request log entry not found", id=rid)

    # access control:
    # If we have a resolved client_id and the target has a client_id, enforce same-client.
    # If target client_id is null/empty, allow.
    tgt_cid = target.get("client_id")
    if isinstance(tgt_cid, str) and tgt_cid.strip():
        if resolved_cid is not None and tgt_cid.strip() != resolved_cid:
            hf_requests = _load("hf_requests.json")
            for row in hf_requests:
                if row.get("id") == req_id:
                    row["status"] = "failed"
                    row["http_status_code"] = 403
                    row["error_message"] = "request belongs to a different client"
                    row["finished_at"] = _now_iso()
                    row["cache_hit"] = False
                    row["updated_at"] = _now_iso()
                    _save("hf_requests.json", hf_requests)
                    break
            return _err("UNAUTHORIZED", "request belongs to a different client", id=rid)

    # succeed
    hf_requests = _load("hf_requests.json")
    for row in hf_requests:
        if row.get("id") == req_id:
            row["status"] = "succeeded"
            row["http_status_code"] = 200
            row["error_message"] = None
            row["result_count"] = 1
            row["finished_at"] = _now_iso()
            row["cache_hit"] = True
            row["updated_at"] = _now_iso()
            _save("hf_requests.json", hf_requests)
            break

    # return only useful fields + full row
    return {
        "request": target,
        "meta": {
            "request_id": req_id,
            "cache_hit": True,
        },
    }

def refresh_hub_entity(entity_type, repo_id, hf_token=None, force=None, **_extra):
    import json, os, datetime, time, hashlib, urllib.request, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0454000" if __import__("os").path.isdir("./environment_mix/0454000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    # Policy knobs (offline-friendly defaults)
    TTL_SECONDS = 24 * 3600  # cache TTL window
    RATE_LIMIT_PER_MINUTE = 60  # per client_id+tool_name

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _mk_id(prefix, existing_ids):
        rnd = hashlib.sha256(f"{now.timestamp()}:{os.getpid()}:{time.time()}:{prefix}".encode("utf-8")).hexdigest()[:10]
        base = f"{prefix}_{rnd}_"
        c = 1
        while f"{base}{c}" in existing_ids:
            c += 1
        return f"{base}{c}"

    def _normalize_params(params):
        def norm(x):
            if isinstance(x, str):
                return x.strip()
            if isinstance(x, list):
                return [norm(i) for i in x]
            if isinstance(x, dict):
                return {k: norm(x[k]) for k in sorted(x.keys())}
            return x
        return norm(params)

    def _cache_key(tool_name, params):
        blob = json.dumps({"tool_name": tool_name, "params": _normalize_params(params)}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _caller_client_id():
        if hf_token is None:
            return None
        if not isinstance(hf_token, str):
            return "__invalid__"
        tok = hf_token.strip()
        if tok == "":
            return "__invalid__"
        return tok

    def _enforce_rate_limit(client_id, tool_name):
        # Count running/succeeded/failed in last 60 seconds for this client_id+tool
        reqs = _load("hf_requests.json")
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("tool_name") != tool_name:
                continue
            if r.get("client_id") != client_id:
                continue
            ts = _parse_dt(r.get("created_at")) or _parse_dt(r.get("started_at")) or _parse_dt(r.get("updated_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= RATE_LIMIT_PER_MINUTE:
            return False, cnt
        return True, cnt

    def _log_request_begin(tool_name, params, client_id):
        reqs = _load("hf_requests.json")
        existing_ids = {r.get("id") for r in reqs if isinstance(r, dict)}
        rid = _mk_id("hf_req", existing_ids)
        row = {
            "id": rid,
            "tool_name": tool_name,
            "client_id": client_id,
            "request_params": params,
            "normalized_cache_key": _cache_key(tool_name, params),
            "status": "queued",
            "http_status_code": 200,
            "error_message": None,
            "result_count": None,
            "started_at": None,
            "finished_at": None,
            "cache_hit": False,
            "created_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        reqs.append(row)
        _save("hf_requests.json", reqs)
        return rid

    def _update_req(rid, new_status, http_status=None, error_message=None, result_count=None, cache_hit=None):
        allowed = {
            "queued": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        reqs = _load("hf_requests.json")
        r = None
        for it in reqs:
            if isinstance(it, dict) and it.get("id") == rid:
                r = it
                break
        if r is None:
            return

        cur = r.get("status")
        if cur not in allowed or new_status not in allowed.get(cur, set()):
            if cur in ("queued", "running") and new_status == "failed":
                pass
            else:
                if cur in ("queued", "running"):
                    new_status = "failed"
                else:
                    return

        if new_status in ("queued", "running"):
            r["cache_hit"] = False
        elif cache_hit is not None:
            r["cache_hit"] = bool(cache_hit)

        now2 = datetime.datetime.now(datetime.timezone.utc)
        if new_status == "running":
            r["started_at"] = _iso(now2)
            r["finished_at"] = None
        if new_status in ("succeeded", "failed"):
            if r.get("started_at") is None:
                r["started_at"] = _iso(now2)
            r["finished_at"] = _iso(now2)

        r["status"] = new_status
        r["updated_at"] = _iso(now2)

        if http_status is not None:
            if isinstance(http_status, int) and 100 <= http_status <= 599:
                r["http_status_code"] = http_status
            else:
                r["http_status_code"] = 500
        if error_message is not None:
            r["error_message"] = error_message
        if result_count is not None:
            r["result_count"] = result_count

        sa = _parse_dt(r.get("started_at"))
        fa = _parse_dt(r.get("finished_at"))
        if sa and fa and fa < sa:
            r["finished_at"] = _iso(sa)

        _save("hf_requests.json", reqs)

    # Validate inputs
    if not isinstance(entity_type, str) or entity_type not in ("model", "dataset", "space"):
        return _err("VALIDATION_ERROR", "entity_type must be one of: model, dataset, space")
    if not isinstance(repo_id, str) or repo_id.strip() == "":
        return _err("VALIDATION_ERROR", "repo_id must be a non-empty string")
    repo_id = repo_id.strip()
    if len(repo_id) > 256:
        return _err("VALIDATION_ERROR", "repo_id must not exceed 256 characters")
    if hf_token is not None and (not isinstance(hf_token, str) or hf_token.strip() == ""):
        return _err("VALIDATION_ERROR", "hf_token must be a non-empty string when provided")
    if force is not None and not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "force must be a boolean when provided")
    force = bool(force) if force is not None else False

    client_id = _caller_client_id()
    if client_id == "__invalid__":
        return _err("VALIDATION_ERROR", "hf_token must be a non-empty string when provided")

    # Rate limit
    ok, cnt = _enforce_rate_limit(client_id, "refresh-hub-entity")
    if not ok:
        # Log invocation as failed
        rid_rl = _log_request_begin("refresh-hub-entity", {"entity_type": entity_type, "repo_id": repo_id, "force": force, "hf_token": hf_token}, client_id)
        _update_req(rid_rl, "running")
        _update_req(rid_rl, "failed", http_status=429, error_message="Rate limit exceeded", result_count=0)
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=RATE_LIMIT_PER_MINUTE)

    # Create request log row
    params = {"entity_type": entity_type, "repo_id": repo_id, "force": force}
    if hf_token is not None:
        params["hf_token"] = hf_token
    rid = _log_request_begin("refresh-hub-entity", params, client_id)
    _update_req(rid, "running")

    # Load entities
    entities = _load("hub_entities.json")

    # Find existing unique(entity_type, repo_id)
    existing = None
    for e in entities:
        if isinstance(e, dict) and e.get("entity_type") == entity_type and e.get("repo_id") == repo_id:
            existing = e
            break

    def _is_stale(e):
        ra = _parse_dt(e.get("refreshed_at")) if isinstance(e, dict) else None
        if not ra:
            return True
        age = (datetime.datetime.now(datetime.timezone.utc) - ra).total_seconds()
        return age > TTL_SECONDS

    # If not force and exists and not stale and active: return as cache_hit (no mutation)
    if existing and not force and existing.get("status") == "active" and not _is_stale(existing):
        _update_req(rid, "succeeded", http_status=200, result_count=1, cache_hit=True)
        return {
            "entity": existing,
            "meta": {
                "cache_hit": True,
                "request_id": rid,
                "latency_ms": int((time.time() - t0) * 1000),
            },
        }

    # Attempt upstream refresh (best-effort offline). If upstream unavailable, serve stale if exists.
    def _fetch_upstream():
        # Returns (http_status, data_dict) or (http_status, None) for not found
        # Use public endpoints:
        # model: https://huggingface.co/api/models/{repo_id}
        # dataset: https://huggingface.co/api/datasets/{repo_id}
        # space: https://huggingface.co/api/spaces/{repo_id}
        base = "https://huggingface.co/api/"
        path = {"model": "models", "dataset": "datasets", "space": "spaces"}[entity_type]
        url = base + path + "/" + urllib.parse.quote(repo_id, safe="")
        headers = {"Accept": "application/json"}
        if hf_token is not None:
            headers["Authorization"] = f"Bearer {hf_token.strip()}"
        req = urllib.request.Request(url, headers=headers, method="GET")
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                status = getattr(resp, "status", 200)
                raw = resp.read().decode("utf-8", errors="replace")
                try:
                    data = json.loads(raw) if raw else {}
                except json.JSONDecodeError:
                    data = {}
                return status, data
        except urllib.error.HTTPError as e:
            try:
                status = int(getattr(e, "code", 500))
            except Exception:
                status = 500
            if status == 404:
                return 404, None
            # Other upstream errors
            return status, {"_upstream_error": str(e)}
        except urllib.error.URLError as e:
            return 0, {"_upstream_unavailable": str(e)}
        except TimeoutError as e:
            return 0, {"_upstream_unavailable": str(e)}

    http_status, data = _fetch_upstream()

    # Upstream not found
    if http_status == 404:
        _update_req(rid, "failed", http_status=404, error_message="Upstream repo not found", result_count=0)
        return _err("NOT_FOUND", "Upstream repo does not exist", repo_id=repo_id, entity_type=entity_type)

    # Upstream unavailable or errored: serve stale if possible, else error
    if http_status == 0 or (http_status >= 400 and http_status != 404):
        if existing:
            # Mark stale on read if TTL exceeded
            if _is_stale(existing) and existing.get("status") == "active":
                # Transition active->stale
                existing["status"] = "stale"
                existing["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                # Do not change refreshed_at if refresh failed
                _save("hub_entities.json", entities)
            _update_req(rid, "succeeded", http_status=200, result_count=1, cache_hit=True)
            return {
                "entity": existing,
                "meta": {
                    "cache_hit": True,
                    "served_stale": True,
                    "upstream_http_status": http_status if http_status != 0 else None,
                    "request_id": rid,
                    "latency_ms": int((time.time() - t0) * 1000),
                },
            }
        _update_req(rid, "failed", http_status=502, error_message="Upstream unavailable", result_count=0)
        return _err("CONFLICT", "Upstream unavailable and no cached entity exists to serve", upstream_http_status=http_status)

    # Successful upstream: map into our schema and upsert
    # Extract best-effort fields
    def _as_tags(d):
        # Consistent tags behavior: treat tags as list of non-empty strings if present; otherwise empty.
        tags = []
        if isinstance(d, dict):
            t = d.get("tags")
            if isinstance(t, list):
                for x in t:
                    if isinstance(x, str):
                        s = x.strip()
                        if s:
                            tags.append(s)
        # De-dupe preserving order
        seen = set()
        out = []
        for s in tags:
            if s not in seen:
                seen.add(s)
                out.append(s)
        return out

    def _safe_int(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return int(v)
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        return None

    def _extract_author(d):
        if not isinstance(d, dict):
            return None
        for k in ("author", "owner", "organization", "user"):
            v = d.get(k)
            if isinstance(v, str) and v.strip():
                return v.strip()
        # Many HF APIs expose "id" like "google/bert..." - author is part before '/'
        if isinstance(repo_id, str) and "/" in repo_id:
            return repo_id.split("/", 1)[0]
        return None

    def _extract_name_desc(d):
        if not isinstance(d, dict):
            return None, None
        name = d.get("modelId") or d.get("id") or d.get("name") or d.get("title")
        if isinstance(name, str):
            name = name.strip()
        else:
            name = None
        desc = d.get("description") or d.get("cardData", {}).get("summary") if isinstance(d.get("cardData"), dict) else d.get("cardData")
        if isinstance(desc, str):
            desc = desc.strip()
        else:
            desc = None
        return name, desc

    tags = _as_tags(data)
    author = _extract_author(data)
    name, desc = _extract_name_desc(data)
    downloads = _safe_int(data.get("downloads") if isinstance(data, dict) else None)
    likes = _safe_int(data.get("likes") if isinstance(data, dict) else None)
    if downloads is not None and downloads < 0:
        downloads = None
    if likes is not None and likes < 0:
        likes = None

    # lastModified might be ISO
    last_modified_at = None
    if isinstance(data, dict):
        lm = data.get("lastModified") or data.get("last_modified") or data.get("updatedAt")
        dt = _parse_dt(lm) if isinstance(lm, str) else None
        last_modified_at = _iso(dt) if dt else None

    sdk = None
    if entity_type == "space" and isinstance(data, dict):
        s = data.get("sdk")
        if isinstance(s, str) and s.strip():
            sdk = s.strip()

    # Build/Update entity row
    entities = _load("hub_entities.json")
    existing_ids = {e.get("id") for e in entities if isinstance(e, dict)}
    if existing is None:
        ent = {
            "id": _mk_id("hub", existing_ids),
            "entity_type": entity_type,
            "repo_id": repo_id,
            "author": author,
            "name": name,
            "description": desc,
            "tags": tags,
            "sdk": sdk if entity_type == "space" else None,
            "downloads": downloads,
            "likes": likes,
            "last_modified_at": last_modified_at,
            "card_data": data.get("cardData") if isinstance(data, dict) else None,
            "status": "active",
            "refreshed_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "created_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        entities.append(ent)
    else:
        # lifecycle transitions for status: stale->active or active->active
        prev_status = existing.get("status")
        if prev_status == "deleted":
            _update_req(rid, "failed", http_status=409, error_message="Cannot refresh deleted entity", result_count=0)
            return _err("INVALID_TRANSITION", "Cannot refresh a deleted entity", current_status="deleted")

        existing["author"] = author
        existing["name"] = name
        existing["description"] = desc
        existing["tags"] = tags
        existing["sdk"] = sdk if entity_type == "space" else None
        existing["downloads"] = downloads
        existing["likes"] = likes
        existing["last_modified_at"] = last_modified_at
        existing["card_data"] = data.get("cardData") if isinstance(data, dict) else existing.get("card_data")
        existing["refreshed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        existing["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        # transition stale->active if needed
        if prev_status == "stale":
            existing["status"] = "active"
        elif prev_status == "active":
            existing["status"] = "active"
        elif prev_status is None:
            existing["status"] = "active"

        ent = existing

    # Validate core constraints best-effort; if invalid, fail without writing broken data
    if not isinstance(ent.get("tags"), list) or any((not isinstance(t, str) or not t.strip()) for t in ent.get("tags")):
        _update_req(rid, "failed", http_status=500, error_message="Invalid tags data after refresh", result_count=0)
        return _err("CONFLICT", "Upstream returned invalid tags data")
    if ent.get("sdk") is not None and ent.get("entity_type") != "space":
        _update_req(rid, "failed", http_status=500, error_message="Invalid sdk data after refresh", result_count=0)
        return _err("CONFLICT", "Upstream returned sdk for non-space entity")

    _save("hub_entities.json", entities)

    _update_req(rid, "succeeded", http_status=200, result_count=1, cache_hit=False)
    return {
        "entity": ent,
        "meta": {
            "cache_hit": False,
            "request_id": rid,
            "upstream_http_status": http_status,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }
